<?php require __DIR__.'/bootstrap.php';if(current_user())redirect('index.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$q=db()->prepare('SELECT * FROM users WHERE email=? AND is_active=1');$q->execute([trim($_POST['email']??'')]);$user=$q->fetch();if($user&&password_verify($_POST['password']??'',$user['password_hash'])){session_regenerate_id(true);$_SESSION['user']=['id'=>$user['id'],'name'=>$user['name'],'role'=>$user['role']];redirect('dealer-dashboard.php');}$error='Invalid email or password.';}page_top('Login');?><form class="form-card" method="post"><h1>Dealer login</h1><?php if($error):?><p class="error"><?=e($error)?></p><?php endif?><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Email</label><input name="email" type="email" required><label>Password</label><input name="password" type="password" required><button class="button">Login</button></form><?php page_bottom();
